// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait TargetStepReadinessQualifier_supervisorProcess_targetStepReadinessQualifier_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_targetStepReadinessQualifier)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_targetStepReadinessQualifier)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_targetStepReadinessQualifier)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_targetStepReadinessQualifier)
  }

  /** helper function to set the values of all input ports.
   * @param readinessObservation payload for data port readinessObservation
   * @param flowContext payload for data port flowContext
   */
  def put_concrete_inputs(readinessObservation : Factory_Flow.StepReadinessObservation,
                          flowContext : Factory_Flow.FlowContext): Unit = {
    put_readinessObservation(readinessObservation)
    put_flowContext(flowContext)
  }


  /** helper function to check TargetStepReadinessQualifier_supervisorProcess_targetStepReadinessQualifier's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param targetFact method that will be called with the value of the outgoing data
   *        port 'targetFact'.
   */
  def check_concrete_output(targetFact: Factory_Flow.TargetQualification.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val targetFactValue: Factory_Flow.TargetQualification.Type = get_targetFact().get
    if(!targetFact(targetFactValue)) {
      testFailures = testFailures :+ st"'targetFact' did not match expected: value of the outgoing data port is ${targetFactValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_readinessObservation(value : Factory_Flow.StepReadinessObservation): Unit = {
    Art.insertInInfrastructurePort(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_targetStepReadinessQualifier.operational_api.readinessObservation_Id, Factory_Flow.StepReadinessObservation_Payload(value))
  }

  // setter for in DataPort
  def put_flowContext(value : Factory_Flow.FlowContext): Unit = {
    Art.insertInInfrastructurePort(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_targetStepReadinessQualifier.operational_api.flowContext_Id, Factory_Flow.FlowContext_Payload(value))
  }

  // getter for out DataPort
  def get_targetFact(): Option[Factory_Flow.TargetQualification.Type] = {
    val value: Option[Factory_Flow.TargetQualification.Type] = get_targetFact_payload() match {
      case Some(Factory_Flow.TargetQualification_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port targetFact.  Expecting 'Factory_Flow.TargetQualification_Payload' but received ${v}")
      case _ => None[Factory_Flow.TargetQualification.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_targetFact_payload(): Option[Factory_Flow.TargetQualification_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_targetStepReadinessQualifier.initialization_api.targetFact_Id).asInstanceOf[Option[Factory_Flow.TargetQualification_Payload]]
  }

}
